// CHANGE THIS PER SHEET
const ALLOWED_CODE = "352";

const row = $('Get All Numbers from Row').first().json;

const wirelessFields = [
  'Wireless - Primary',
  'Wireless 1',
  'Wireless 2',
  'Wireless 3',
  'Wireless 4'
];

// Collect, normalize, and FILTER numbers by area code
const numbers = wirelessFields
  .map(field => row[field])
  .filter(value => typeof value === 'string' && value.trim() !== '')
  .map(value => {
    const clean = value.replace(/\D/g, "");
    const areaCode =
      clean.length === 11 ? clean.slice(1, 4) : clean.slice(0, 3);
    return { clean, areaCode };
  })
  // ✅ KEEP ONLY 352
  // .filter(n => n.areaCode === ALLOWED_CODE)
  .map(n => n.clean);

// Do NOT stop the workflow even if numbers is empty
return [
  {
    json: {
      row_number: row.row_number,
      status_message: row['Status Message'] || '',
      numbers
    }
  }
];

const state = $getWorkflowStaticData('global');

if (!state.initialized) {
  state.queue = [];
  state.currentRow = null;
  state.processingRowId = null;
  state.allowed = true;

  state.twilioLimits = {};
  for (let i = 1; i <= 10; i++) {
    state.twilioLimits[i] = {
      dailyLimit: 5,
      usedToday: 0
    };
  }

  state.initialized = true;
}

return [{ json: { 
  initialized: true,
  queue:state.queue,
  currentRow:state.currentRow,
  processingRowId:state.processingRowId,
  twilioLimits:state.twilioLimits,
  allowed:state.allowed,
                } }];

const state = $getWorkflowStaticData('global');

const incomingNumbers = $('Get All Numbers From Row By Row').first().json.numbers;
const rowNumber = $('Get All Numbers From Row By Row').first().json.row_number;

for (const number of incomingNumbers) {
  const exists = state.queue.some(
    q => q.number === number && q.row === rowNumber
  );

  if (!exists) {
    state.queue.push({
      number,
      row: rowNumber,
      status: 'QUEUED'
    });
  }
}

return [{ json: { queueSize: state.queue.length,
                incomingNumbers:incomingNumbers,
                rowNumber:rowNumber,
                } }];

const state = $getWorkflowStaticData('global');
const key = 1; // Twilio number index (1–10)

const limit = state.twilioLimits[key];

// Defensive check (in case state was reset)
if (!limit) {
  state.allowed = false;
  return [{ json: { allowed: false, key, reason: 'Limit not found' } }];
}

// Check daily limit
if (limit.usedToday >= limit.dailyLimit) {
  state.allowed = false;

  return [{
    json: {
      allowed: false,
      key,
      usedToday: limit.usedToday,
      dailyLimit: limit.dailyLimit
    }
  }];
}

// Allowed case
state.allowed = true;

return [{
  json: {
    allowed: true,
    key,
    usedToday: limit.usedToday,
    dailyLimit: limit.dailyLimit
  }
}];

