const state = $getWorkflowStaticData('global');

if (state.processingRowId) {
  return [{ json: { action: 'BUSY' } }];
}

if (state.queue.length === 0) {
  return [{ json: { action: 'EMPTY' } }];
}

const item = state.queue.shift();
state.processingRowId = item.row;

return [{
  json: {
    action: 'PROCESS',
    number: item.number,
    row: item.row,
    length:state.queue.length,
    queue:state.queue,
    id:state.processingRowId,
  }
}];

