const key = 2;

const limit = state.twilioLimits[key];

// Reset row processing marker AFTER successful send cycle (safe here)
state.processingRowId = null;

// Check limit BEFORE increment
if (limit.usedToday >= limit.dailyLimit) {
  state.allowed = false;
  return [{
  json: {
    allowed: false,
    key,
    usedToday: limit.usedToday,
    dailyLimit: limit.dailyLimit,
