function clean(v) {
  return (v || "").toString().trim();
}

const owner = clean($json["Owner 1 First Name"]) || "there";
const address = clean($json["Address"]);
const city = clean($json["City"]);
const state = clean($json["State"]);

// Build location safely
const location = [
  address,
  city,
  state
].filter(Boolean).join(", ");

// Single-line SMS body (no \n)
const body = `Hi ${owner}, we're reaching out about your property at ${location}. Interested in discussing?`;

return [
  {
    ...$json,
    body
  }
];

const majorCarriers = [
  't-mobile',
  'at&t',
  'metropcs',
  'verizon',
  'boost'
];

return items.map(item => {
  const input = item.json;

  const lineType = String(input.line_type_intelligence?.type || '').toLowerCase();
  const carrier = String(input.line_type_intelligence?.carrier_name || '').toLowerCase();

  const isMobile = lineType === 'mobile';

  let score = 0;
  const reasons = [];

  // +20 area code match
  if (input.area_code === input.allowed_code) {
    score += 20;
    reasons.push('market area code match');
  }

  // +20 mobile
  if (isMobile) {
    score += 20;
    reasons.push('mobile');
  }

  // +10 major carrier
  if (majorCarriers.some(c => carrier.includes(c))) {
    score += 10;
    reasons.push('major carrier');
  }

  // optional tie-breaker bonus
  if (input.field === 'Wireless - Primary') {
    score += 1;
    reasons.push('primary tie-breaker');
  }

  return {
    json: {
      ...input,
      score,
      reasons,

      // New condition:
      // Score does not decide eligibility anymore.
      // Only confirmed mobile numbers are eligible.
      eligible: isMobile
    }
  };
});

const grouped = {};

for (const item of items) {
  const row = item.json.row_number;

  if (!grouped[row]) {
    grouped[row] = {
      row_number: row,
      status_message: item.json.status_message || '',
      numbers: [],
      scored_numbers: []
    };
  }

  grouped[row].scored_numbers.push(item.json);
}

