const ACCOUNT_SID = 'AC0eed0a0301b825f8b65f07bc44522bac';
const AUTH_TOKEN = '4ba62cb7cc8cfd561eb27d0a7377dadc';
const FROM_NUMBER = '+13529223812';

const input = $input.first().json;
const MESSAGE_BODY = $node["Get All Numbers from Row"].json.body;

// ===== EXTRA FIELDS FOR SHEET =====
const STAGE = input.stage || $node["Get All Numbers from Row"].json.stage || "0";
const SHEET_NAME = input.sheet_name || $node["Get All Numbers from Row"].json.sheet_name || "352";
const TIME_TO_SENT = new Date().toISOString();

// ===== INPUT PROCESSING =====
const raw = String(
  input.number ||
  input.numbers?.[0] ||
  input.scored_numbers?.[0]?.phone_number ||
  ""
);

let formattedNumber = raw.trim();

if (!formattedNumber.startsWith('+')) {
  const digits = formattedNumber.replace(/\D/g, '');
  formattedNumber = digits.startsWith('1') ? `+${digits}` : `+1${digits}`;
}

// Twilio endpoint
const url = `https://api.twilio.com/2010-04-01/Accounts/${ACCOUNT_SID}/Messages.json`;
const authHeader = Buffer.from(`${ACCOUNT_SID}:${AUTH_TOKEN}`).toString('base64');

try {
  const body =
    `To=${encodeURIComponent(formattedNumber)}` +
    `&From=${encodeURIComponent(FROM_NUMBER)}` +
    `&Body=${encodeURIComponent(MESSAGE_BODY)}`;

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      Authorization: `Basic ${authHeader}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body,
  });

  return [{
    json: {
      status: 'SENT',
      sid: response.sid,
      From: FROM_NUMBER,
      To: formattedNumber,
      Time_To_Sent: TIME_TO_SENT,
      Message_Body: MESSAGE_BODY,
      Stage: STAGE,
      Sheet_name: SHEET_NAME
    }
  }];
} catch (err) {
  return [{
    json: {
      status: 'FAILED',
      error: err?.response?.body || err.message,
      From: FROM_NUMBER,
      To: formattedNumber,
      Time_To_Sent: TIME_TO_SENT,
      Message_Body: MESSAGE_BODY,
      Stage: STAGE,
      Sheet_name: SHEET_NAME
    }
  }];
}

